double calculate_total_revenue(const std::vector<voucher>& vouchers) {
  double total = 0.0;
  for (const auto& voucher : vouchers) {
    total += voucher.amount;
  }
  return total;
}

int calculate_voucher_type_count(const std::vector<voucher>& vouchers, const std::string& type) {
  int count = 0;
  for (const auto& voucher : vouchers) {
    if (voucher.type == type) {
      count++;
    }
  }
  return count;
}

